INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(126022, 'ruRU', '', 'Хорошо, используй точку спуска. Вниз!', 24330),
(126025, 'ruRU', '', 'Нет времени терять, Клинок Тени. Идём.', 24330),
(126026, 'ruRU', '', 'Нынче мы празднуем годовщину звона Скарабеева Гонга. Увидишь всякие гулянья по всему Силитусу нынче.$b$bЧасть традиции - призыв огромных жуков из трёх силитидных гнёзд. А для этого нам надо мяса. Горы мяса.$b$bПоможешь, а?', 24330),
(126033, 'ruRU', '', 'Объединив наши силы, мы повергнем Пылающий Легион!', 24330),
(126034, 'ruRU', '', 'Будут сложены сказания, будут спеты песни о славе, что ждёт нас в этот день.', 24330),
(126041, 'ruRU', '', 'Отлично! Я прикончу тебя сам!', 24330),
(126045, 'ruRU', '', 'Я не думал об этом с тех пор... ну, с тех пор как старый друг спросил об этом незадолго до того, как покинул этот мир.', 24330),
(126046, 'ruRU', '', 'После смерти Антонидаса я решил спрятать диск. Не было смысла продолжать свои исследования над ним.', 24330),
(126047, 'ruRU', '', 'Но если ты думаешь, что сможешь закончить то, что начал Антонидас, то эта вещь твоя. Удачи тебе с этим, архимаг $n.', 24330),
(126053, 'ruRU', '', 'Похоже, ты был прав, чужак. Спасибо, что помог мне найти свой путь.', 24330),
(126054, 'ruRU', '', 'Я всегда буду помнить твои деяния. Однажды их запомнит и весь Тайдскорн.', 24330),
(126066, 'ruRU', '', 'Д\'Бинн! Ты слышишь меня? Когда меня освободят, я убью каждого последнего ловца за то, что они сделали с нами!', 24330),
(126073, 'ruRU', '', 'Хватит тянуть время! Где твой провидец?!', 24330),
(126074, 'ruRU', '', 'Идём, дитя. Мы должны спасти моё племя.', 24330),
(126085, 'ruRU', '', 'Иди вперёд отсюда, а я пойду в другую сторону. Я найду тебя позже.', 24330),
(126086, 'ruRU', '', 'Как ты рассчитываешь использовать силу Камня Рока, если не можешь даже открыть свой собственный портал? Глупое дитя.', 24330),
(126093, 'ruRU', '', 'Не смотри на меня как на одного из своих прислужников, $r. Для меня ты всего лишь дитя.', 24330),
(126094, 'ruRU', '', 'А в этом углу... чайка? Это что, Око Азшары?', 24330),
(126096, 'ruRU', '', 'Похоже, для этой... штуковины каждый день - Тыквовин. Повизжите громче для Улисс!', 24330),
(126097, 'ruRU', '', 'Прямиком из сумрачных дорог Темнолесья, это Стежок!', 24330),
(126098, 'ruRU', '', 'Это что, гигантский гриб? Похоже, сейчас будет жутковато!', 24330),
(126099, 'ruRU', '', 'О, громадный ламантин! Он здесь, чтобы скрепить сделку... ГИБЕЛЬПЛАВНИК!', 24330),
(126100, 'ruRU', '', 'А вот и их соперник, Билл, инженер по уборке на службе смерти! Погодите... что? Билл! Ты что здесь делаешь?', 24330),
(126102, 'ruRU', '', 'А теперь представляем дренея, одержимого коллекционированием питомцев, это Эш\'кацуум!', 24330),
(126103, 'ruRU', '', 'В другом углу - мастер теней И внутреннего освещения одновременно... это Теневой мастер Аамин!', 24330),
(126104, 'ruRU', '', 'В другом углу - соперник настолько древний, что никто не помнит его настоящего имени. Назовём его Древний Змей!', 24330),
(126105, 'ruRU', '', 'В другом углу... просто очень большой динозавр!', 24330),
(126106, 'ruRU', '', 'Будьте добры, вставьте золотую монету для битвы с Мастером Паку!', 24330),
(126107, 'ruRU', '', 'А в другом углу - не один, не два, а целых ТРИ смертоносных дворфа из Совета Боевого Молота!', 24330),
(126108, 'ruRU', '', 'Также выходит на арену... уродливая гномская штуковина, которая играет музыку.', 24330),
(126109, 'ruRU', '', 'А наш другой соперник - червь с серьёзной слабостью к огню. Да ладно, Карл! Ты не знал, что пламя может убить?', 24330),
(126110, 'ruRU', '', 'А в другом углу - охотник непостижимого, захватывающего, потрясающего великолепия! Это Джонни Крутой!', 24330),
(126111, 'ruRU', '', 'А теперь соперник, что стоил нам так дорого... это Рэй Д. Тир!', 24330),
(126112, 'ruRU', '', 'Распаляйтесь ради джинна, который буквально растопит ваше сердце, это Бёрнстачо!', 24330),
(126113, 'ruRU', '', 'А в другом углу - это ужасное трио... Хадсон, Стаффшрю и Дюпре из команды "Дозор огров"!', 24330),
(126114, 'ruRU', '', 'А теперь немного вышибающих душу битов из музыкального андерграунда - это Твэк Ю и его танцоры!', 24330),
(126115, 'ruRU', '', 'В другом углу - пират с убийственным пониманием словосочетания "пушка на голове"! Сложите крюки вместе ради Блэкманжа!', 24330),
(126117, 'ruRU', '', 'Ты не ведаешь, что говоришь. Отдай это мне!', 24330),
(126119, 'ruRU', '', 'Избалованный щенок! Этот Камень Рока не покинет меня!', 24330),
(126147, 'ruRU', '', 'Благодарствую, если б не был в цепях, я б сам отвесил этому уродливому громиле знатную порку!', 24330);
